          "id": "C1-02",
          "zh": "穿过白的云 往风下 只剩我一个"
        },
        {
          "id": "C1-03",
          "zh": "天光初泛白 快走 别回头"
        },
        {
          "id": "C1-04",
          "zh": "草的腥与魂 搅成一股 涌上来"
        },
        {
          "id": "C1-05",
          "zh": "穿过风 再穿 过云层 远去"
        },
        {
          "id": "C1-06",
          "zh": "穿过白的云 往风下 只剩我一个"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "接住这阵风 撞开一片花"
        },
        {
          "id": "C1-02",
          "zh": "穿出云层去 顺着风 只剩我一个"
        },
        {
          "id": "C1-03",
          "zh": "天刚泛白时 快走别回头"
        },
        {
          "id": "C1-04",
          "zh": "青草腥气里 混着魂魄 飘散开"
        },
        {
          "id": "C1-05",
          "zh": "穿过风 别停 穿过天 别停"
        },
        {
          "id": "C1-06",
          "zh": "穿出云层去 顺着风 只剩我一个"
        }
      ]
    }
  ]
}

